        "ev": "링슈트라세(Ringstraße) 야간 산책. 프란츠 요제프 1세가 1857년 중세 성벽을 허물고 만든 황제의 대로. 국립오페라(Staatsoper)·부르크극장(Burgtheater)·미술사 박물관·국회의사당이 일직선. 저녁: Gasthaus Pöschl 또는 Meixner (빈 전통 뷔르스텔스탄트, 소시지 가게 €3~5).",
